		       INTO dtmeta.tb_meta_keyword
			 ( kywrd_norm
			 , kywrd_disp
			 , kywrd_influx_tag
             , kywrd_lang_mtcd
             , kywrd_recnt_dt
             , kywrd_reg_dt
			 ) VALUES 
			 ( 
			   #{kywrdNorm}
			 , #{kywrdDisp}
			 , #{kywrdInfluxTag}
			 , #{kywrdLangMtcd}
			 , current_timestamp
             , current_timestamp
			 )
